  obPackageSource: ["安装包来源", "Package source", "安裝包來源", "パッケージの入手元", "패키지 출처", "Paketquelle", "Source des paquets", "Origen de los paquetes", "Origem dos pacotes", "Источник пакетов"],
  obSourceDownload: ["自动下载（推荐）", "Download automatically (recommended)", "自動下載（建議）", "自動ダウンロード（推奨）", "자동 다운로드(권장)", "Automatisch herunterladen (empfohlen)", "Télécharger automatiquement (recommandé)", "Descargar automáticamente (recomendado)", "Baixar automaticamente (recomendado)", "Скачать автоматически (рекомендуется)"],
  obSourceLocal: ["使用已下载的安装包", "Use downloaded packages", "使用已下載的安裝包", "ダウンロード済みのパッケージを使う", "이미 받은 패키지 사용", "Bereits heruntergeladene Pakete verwenden", "Utiliser des paquets déjà téléchargés", "Usar paquetes ya descargados", "Usar pacotes já baixados", "Использовать скачанные пакеты"],
  obLocalStrata: ["Strata 安装包", "Strata package", "Strata 安裝包", "Strata パッケージ", "Strata 패키지", "Strata-Paket", "Paquet Strata", "Paquete de Strata", "Pacote do Strata", "Пакет Strata"],
  obLocalEngine: ["引擎安装包", "Engine package", "引擎安裝包", "エンジンパッケージ", "엔진 패키지", "Engine-Paket", "Paquet du moteur", "Paquete del motor", "Pacote do motor", "Пакет движка"],
  obChooseFile: ["选择文件…", "Choose file…", "選擇檔案…", "ファイルを選択…", "파일 선택…", "Datei auswählen…", "Choisir un fichier…", "Elegir archivo…", "Escolher arquivo…", "Выбрать файл…"],
